import {archiveSource} from './company-storage.js';
function visualSettings(){try{const v=JSON.parse(storage.getItem('upravdom.visuals'));return {traffic:typeof v?.traffic==='boolean'?v.traffic:true,equipment:typeof v?.equipment==='boolean'?v.equipment:true};}catch{return {traffic:true,equipment:true};}}
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toast=document.querySelector('#toast'),importInput=document.querySelector('#importFile');
const storage=(()=>{try{return window.localStorage;}catch{return {getItem(){throw Error('Хранилище недоступно');},setItem(){throw Error('Хранилище недоступно');}};}})();
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>Math.round(n).toLocaleString('ru-RU')+' ₽',names=['Сантехники','Электрики','Ремонтники'],colors=['#58bfee','#f4cd62','#61d9a0'];
