let loaded=E.load(storage),state=E.upgradeTerritoryCompany(loaded.state),blocked=loaded.blocked,settings=loadSettings(storage),screen='menu',sub='crews',paused=true,speed=1,selected=null,selectedCrew=null,page=0,saveError=false;
let view={x:768,y:510,scale:.3},last=performance.now(),fraction=0,menuSeed=null;
let visuals=visualSettings(),queueOpen=false,regionChoice=0,catalogOpen=false;
let incidentTab='call',radioSeen=state?.operations?.radio.at(-1)?.id??0;
let territoryTab='districts',fleetFilter='all';
let cityArtLoaded=false;
function ensureCityArt(){if(!cityArtLoaded){cityArtLoaded=true;loadArt(redraw);}}
// Non-destructive compatibility with old 0.6 parking at a common crossroads.
function restoreParkingBays(){if(!state)return;const center=depot(state.seed,state.region);for(const crew of state.crews){if(crew.status==='idle'&&Math.hypot(crew.point[0]-center[0],crew.point[1]-center[1])<.1)crew.point=parkingBay(state.seed,state.region,crew.id);}}
restoreParkingBays();
root.classList.add('campaignApp');document.body.classList.add('campaignMode');
const selectedCall=()=>state?.calls.find(c=>c.mission===selected);
function message(text){toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),4000);}
function persist(){if(!state||blocked)return;try{E.save(storage,state);saveError=false;}catch{saveError=true;message('Сохранить не удалось. Экспортируйте компанию через настройки.');}}
function close(){if(dialog.contains(importInput))document.body.append(importInput);dialog.close();dialog.innerHTML='';last=performance.now();}
function modal(title,body,footer=''){if(dialog.contains(importInput))document.body.append(importInput);dialog.classList.toggle('opReportDialog',!!footer);dialog.innerHTML=`<header class="campaignDialogHead"><h2 id="dialogTitle">${esc(title)}</h2>${button('close',icon('close'),'aria-label="Закрыть"','iconButton')}</header><div class="campaignDialogBody">${body}</div>${footer?'<footer class="opDialogFooter">'+footer+'</footer>':''}`;if(!dialog.open)dialog.showModal();last=performance.now();}
function migrationArchive(){try{return storage.getItem(E.MIGRATION_ARCHIVE);}catch{return null;}}
function progressionArchive(){try{return storage.getItem(E.PROGRESSION_ARCHIVE);}catch{return null;}}
function territoryArchive(){try{return archiveSource(storage.getItem(E.TERRITORY_ARCHIVE));}catch{return null;}}
function operationArchive(){try{return storage.getItem(E.OPERATION_ARCHIVE);}catch{return null;}}
function legacyAvailable(){try{return !!storage.getItem('upravdom.v1');}catch{return false;}}
function syncMode(){document.body.classList.toggle('operationsMode',!!state?.operations);}
function menu(){syncMode();screen='menu';paused=true;selected=null;root.innerHTML=`<section class="campaignMenu artMenu" aria-label="Главное меню">
 <div class="menuGlow" aria-hidden="true"></div>
 <div class="campaignBrand"><span class="brandOverline">СИМУЛЯТОР КОММУНАЛЬНОЙ ДИСПЕТЧЕРСКОЙ</span><div class="brandGlyph" aria-hidden="true">${icon('home')}</div><h1>УПРАВ<span>ДОМ</span></h1><p>Управляющая компания «Уют»</p></div>
 <div class="campaignMenuButtons">${state&&!blocked?button('continue','Продолжить <span aria-hidden="true">'+icon('play')+'</span>','','primary'):button('new','Новая игра <span aria-hidden="true">'+icon('arrow')+'</span>','','primary')}${state&&!blocked?button('new','Новая компания <span aria-hidden="true">'+icon('plus')+'</span>','','subtle'):button('continue','Продолжить <span aria-hidden="true">'+icon('play')+'</span>',!legacyAvailable()||blocked?'disabled':'','subtle')}${button('settings','Настройки <span aria-hidden="true">'+icon('gear')+'</span>','','subtle')}${T.enabled(state)?'<p class="menuContinueInfo">'+esc(T.areaName(state))+' · '+esc(T.layout(state).name)+'<br>День '+state.day+' · '+state.operations.houses.length+' домов · '+rub(state.money)+'</p>':''}<small class="menuVersion">${APP_VERSION}</small></div>
 </section>`;}
function top(title){return `<header class="campaignHeader">${button('menu',icon('chevron'),'aria-label="Главное меню"','iconButton')}<div><small>УПРАВДОМ · ${T.enabled(state)?T.AREA_NAMES[state.region]+' область':(state.region+1)+'/20'}</small><strong>${esc(title)}</strong></div><span>${rub(state.money)}</span>${button('settings',icon('gear'),'aria-label="Настройки"','iconButton')}</header>`;}
function navigate(next){syncMode();if(state?.operations&&next==='map'&&!view.initialized)focusServiceArea(view,state,root.clientWidth,root.clientHeight-58);if(dialog.open)close();screen=next;paused=true;last=performance.now();if(next==='map'&&!view.initialized){focusDistrict(view,state.region);view.scale=.47;const parking=state.crews[0]?.point;if(parking){view.x=parking[0];view.y=parking[1]+105;}else{const center=depot(state.seed,state.region);view.x=center[0];view.y=center[1];}view.initialized=true;}paint();}
// The 5×4 grid is the actual campaign district layout. Locked districts are visible but do not unlock early.
