 if(a==='op-disband'){modal('Распустить бригаду Б'+(id+1)+'?',`<p>Сотрудники и машина останутся в компании. Перед сменой потребуются три сформированные службы.</p>${button('disband','Распустить',`data-id="${id}"`,'primary wide')}`);return true;}
