 if(a==='op-autoCrew'){O.Career.reserveCrew(state,id);persist();if(T.enabled(state))preparation();else modal('Диспетчерская',OperatorUI.dispatchers(state));return true;}
 if(a==='op-manual'){const c=state.calls.find(c=>c.mission===Number(el.dataset.call));if(c)c.manual=!c.manual;update();return true;}
 if(a==='op-openDistrict'||a==='op-switchDistrict'){if(a==='op-openDistrict')O.openDistrict(state,id,E.log);else O.switchDistrict(state,id);view.initialized=false;selected=null;selectedCrew=null;sub='crews';navigate('prep');update();return true;}
